code_sketch:
type Money struct {
    Amount   decimal.Decimal // exact base-10, never float64
    Currency string          // ISO 4217, e.g. "USD"
}

func (a Money) Add(b Money) (Money, error) {
    if a.Currency != b.Currency {
        return Money{}, ErrCurrencyMismatch
    }
    return Money{a.Amount.Add(b.Amount), a.Currency}, nil
}

